import { path } from '@servicenow/sdk-build-core'
import { createTestContext } from '../test-utils'

describe('JSON plugin tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('JSON objects can be imported and stringified', async () => {
        const project = ctx.createProject()
        project.addFile({
            path: 'src/fluent/foo.json',
            content: `
{
    hello: 'world' // Supports JSON5!
}
`,
        })

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = { red: 'blue' }

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`,
        })

        const diagnostics = (await index.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await index.getRecords()).query()
        expect(record?.get('one').getValue()).toEqual(JSON.stringify({ hello: 'world' }))
        expect(record?.get('two').getValue()).toEqual(JSON.stringify({ red: 'blue' }))
    })

    test('JSON arrays can be imported and stringified', async () => {
        const project = ctx.createProject()
        project.addFile({
            path: 'src/fluent/foo.json',
            content: `
[
    { hello: 'world' }, // Supports JSON5!
    { goodbye: 'moon' },
]
`,
        })

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = [{ red: 'blue' }, { green: 'yellow' }]

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`,
        })

        const diagnostics = (await index.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await index.getRecords()).query()
        expect(record?.get('one').getValue()).toEqual(JSON.stringify([{ hello: 'world' }, { goodbye: 'moon' }]))
        expect(record?.get('two').getValue()).toEqual(JSON.stringify([{ red: 'blue' }, { green: 'yellow' }]))
    })

    test('bidi sync for imported and stringified JSON', async () => {
        const project = ctx.createProject()
        project.addFile({ path: 'src/fluent/foo.json', content: '{ hello: "world" }' })

        const id = project.registerExplicitId('test', 'test')
        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = {
    /* cool formatting */ red: 'blue',
}

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`,
        })

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<record_update>
    <test action="INSERT_OR_UPDATE">
        <sys_id>${id}</sys_id>
        <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
        <one>{"hello":"goodbye"}</one>
        <two>{"red":"green","yellow":"orange"}</two>
    </test>
</record_update>`,
        })

        const index = changedFiles.find((f) => f.getName() === 'index.now.ts')
        const foo = changedFiles.find((f) => f.getName() === 'foo.json')

        expect(index).toBeDefined()
        expect(foo).toBeDefined()
        expect(changedFiles.map((f) => f.getPath())).toHaveLength(2)

        expect(index?.getContent()).toBe(`import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = {
    /* cool formatting */ red: 'green',
    yellow: 'orange',
}

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`)
        expect(foo?.getContent()).toBe('{\n    "hello": "goodbye"\n}')
    })

    test('bidi sync for imported and stringified JSON arrays', async () => {
        const project = ctx.createProject()
        project.addFile({ path: 'src/fluent/foo.json', content: '[{ "hello": "world" }]' })

        const id = project.registerExplicitId('test', 'test')
        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = [/* cool formatting */ { red: 'blue' }]

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`,
        })

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<record_update>
    <test action="INSERT_OR_UPDATE">
        <sys_id>${id}</sys_id>
        <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
        <one>[{"hello":"goodbye"}]</one>
        <two>[{"red":"green","yellow":"orange"}]</two>
    </test>
</record_update>`,
        })

        const index = changedFiles.find((f) => f.getName() === 'index.now.ts')
        const foo = changedFiles.find((f) => f.getName() === 'foo.json')

        expect(index).toBeDefined()
        expect(foo).toBeDefined()
        expect(changedFiles.map((f) => f.getPath())).toHaveLength(2)

        expect(index?.getContent()).toBe(`import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

const bar = [/* cool formatting */ { red: 'green', yellow: 'orange' }]

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
        two: JSON.stringify(bar),
    },
})
`)
        expect(foo?.getContent()).toBe('[\n    {\n        "hello": "goodbye"\n    }\n]')
    })

    test('JSON objects with nested arrays are parsed correctly', async () => {
        const project = ctx.createProject()
        // This structure mimics .claims.json - an object with array values
        // Previously this would incorrectly parse as the first nested array instead of the root object
        project.addFile({
            path: 'src/fluent/foo.json',
            content: `{
    "key_a": ["value1", "value2"],
    "key_b": ["value3"]
}`,
        })

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
    },
})
`,
        })

        const diagnostics = (await index.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await index.getRecords()).query()
        // Should be the full object, not just the first nested array
        expect(record?.get('one').getValue()).toEqual(
            JSON.stringify({ key_a: ['value1', 'value2'], key_b: ['value3'] })
        )
    })

    test('JSON arrays with nested objects are parsed correctly', async () => {
        const project = ctx.createProject()
        // Array at root level containing objects with nested arrays
        project.addFile({
            path: 'src/fluent/foo.json',
            content: `[
    { "name": "item1", "tags": ["a", "b"] },
    { "name": "item2", "tags": ["c"] }
]`,
        })

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'
import foo from './foo.json'

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        one: JSON.stringify(foo),
    },
})
`,
        })

        const diagnostics = (await index.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await index.getRecords()).query()
        // Should be the full array, not just a nested object or array
        expect(record?.get('one').getValue()).toEqual(
            JSON.stringify([
                { name: 'item1', tags: ['a', 'b'] },
                { name: 'item2', tags: ['c'] },
            ])
        )
    })
})
